"""Strict parsing and task metrics for generative outputs."""

from __future__ import annotations

import json
import re
from collections.abc import Iterable

import numpy as np
from sklearn.metrics import accuracy_score, f1_score

_ANSWER = re.compile(r"Answer:\s*", re.IGNORECASE)


def parse_answer(text: str) -> dict[str, object] | None:
    matches = list(_ANSWER.finditer(text))
    start = matches[-1].end() if matches else text.find("{")
    if start < 0:
        return None
    brace = text.find("{", start)
    if brace < 0:
        return None
    try:
        value, _ = json.JSONDecoder().raw_decode(text[brace:])
    except (json.JSONDecodeError, TypeError):
        return None
    return value if isinstance(value, dict) else None


def evaluate_rows(rows: Iterable[dict[str, object]]) -> dict[str, float | int]:
    items = list(rows)
    parsed = [
        item.get("prediction")
        if isinstance(item.get("prediction"), dict)
        else parse_answer(str(item.get("output", "")))
        for item in items
    ]
    metrics: dict[str, float | int] = {
        "n": len(items),
        "parse_validity": sum(prediction is not None for prediction in parsed) / len(items) if items else 0.0,
        "schema_exact_match": (
            float(
                np.mean(
                    [
                        isinstance(prediction, dict) and set(prediction) == set(item["target"])
                        for item, prediction in zip(items, parsed)
                    ]
                )
            )
            if items
            else 0.0
        ),
        "answer_exact_match": (
            float(
                np.mean(
                    [
                        isinstance(prediction, dict) and prediction == item["target"]
                        for item, prediction in zip(items, parsed)
                    ]
                )
            )
            if items
            else 0.0
        ),
    }
    if not items:
        return metrics

    def pairs(key: str) -> tuple[list[object], list[object]]:
        selected = [
            (
                item["target"].get(key),
                prediction.get(key) if isinstance(prediction, dict) else None,
            )
            for item, prediction in zip(items, parsed)
            if key in item["target"]
        ]
        return [pair[0] for pair in selected], [pair[1] for pair in selected]

    y_true, y_pred = pairs("contact")
    if y_true:
        metrics["contact_n"] = len(y_true)
        contact_true = np.asarray([value is True for value in y_true], dtype=bool)
        contact_pred = np.asarray([value is True for value in y_pred], dtype=bool)
        metrics["contact_accuracy"] = float(
            np.mean(
                [
                    isinstance(prediction, bool) and prediction == truth
                    for truth, prediction in zip(y_true, y_pred)
                ]
            )
        )
        metrics["contact_f1"] = float(f1_score(contact_true, contact_pred, pos_label=True, zero_division=0))
    y_true, y_pred = pairs("event_type")
    if y_true:
        metrics["semantics_n"] = len(y_true)
        semantics_true = np.asarray([str(value) for value in y_true], dtype=str)
        semantics_pred = np.asarray([str(value) for value in y_pred], dtype=str)
        metrics["semantics_accuracy"] = float(accuracy_score(semantics_true, semantics_pred))
        metrics["semantics_macro_f1"] = float(
            f1_score(
                semantics_true,
                semantics_pred,
                labels=("free", "intentional", "accidental"),
                average="macro",
                zero_division=0,
            )
        )
    y_true, y_pred = pairs("strongest_joint")
    event_pairs = [(truth, pred) for truth, pred in zip(y_true, y_pred) if truth is not None]
    if event_pairs:
        metrics["strongest_joint_n"] = len(event_pairs)
        metrics["strongest_joint_accuracy"] = float(
            accuracy_score(
                np.asarray([str(pair[0]) for pair in event_pairs], dtype=str),
                np.asarray([str(pair[1]) for pair in event_pairs], dtype=str),
            )
        )
    y_true, y_pred = pairs("onset_ms")
    contact_onsets = [(truth, pred) for truth, pred in zip(y_true, y_pred) if truth is not None]
    errors = []
    for truth, prediction in contact_onsets:
        try:
            errors.append(abs(float(prediction) - float(truth)))
        except (TypeError, ValueError):
            continue
    if contact_onsets:
        metrics["onset_n"] = len(contact_onsets)
        metrics["onset_coverage"] = len(errors) / len(contact_onsets)
    if errors:
        metrics["onset_mae_ms"] = float(np.mean(errors))
        metrics["onset_median_ae_ms"] = float(np.median(errors))
        metrics["onset_p90_ae_ms"] = float(np.quantile(errors, 0.9))
        for tolerance in (10, 25, 50):
            metrics[f"onset_within_{tolerance}ms"] = float(np.mean(np.asarray(errors) <= tolerance))

    y_true, y_pred = pairs("affected_joints")
    if y_true:
        metrics["affected_joints_n"] = len(y_true)
        exact = []
        set_f1 = []
        for truth, prediction in zip(y_true, y_pred):
            truth_list = list(truth) if isinstance(truth, list) else []
            prediction_list = list(prediction) if isinstance(prediction, list) else []
            exact.append(isinstance(prediction, list) and prediction_list == truth_list)
            truth_set = set(truth_list)
            prediction_set = set(prediction_list)
            if not truth_set and not prediction_set:
                set_f1.append(1.0)
            elif not truth_set or not prediction_set:
                set_f1.append(0.0)
            else:
                precision = len(truth_set & prediction_set) / len(prediction_set)
                recall = len(truth_set & prediction_set) / len(truth_set)
                set_f1.append(2 * precision * recall / (precision + recall) if precision + recall else 0.0)
        metrics["affected_joints_exact_match"] = float(np.mean(exact))
        metrics["affected_joints_set_f1"] = float(np.mean(set_f1))

    starts_true, starts_pred = pairs("evidence_start_ms")
    ends_true, ends_pred = pairs("evidence_end_ms")
    intervals = [
        (start, end, predicted_start, predicted_end)
        for start, end, predicted_start, predicted_end in zip(starts_true, ends_true, starts_pred, ends_pred)
        if start is not None and end is not None
    ]
    interval_errors = []
    interval_ious = []
    for start, end, predicted_start, predicted_end in intervals:
        try:
            start = float(start)
            end = float(end)
            predicted_start = float(predicted_start)
            predicted_end = float(predicted_end)
        except (TypeError, ValueError):
            continue
        interval_errors.append((abs(predicted_start - start), abs(predicted_end - end)))
        intersection = max(0.0, min(end, predicted_end) - max(start, predicted_start))
        union = max(end, predicted_end) - min(start, predicted_start)
        interval_ious.append(intersection / union if union > 0 else float(start == predicted_start))
    if intervals:
        metrics["evidence_interval_n"] = len(intervals)
        metrics["evidence_interval_coverage"] = len(interval_errors) / len(intervals)
    if interval_errors:
        metrics["evidence_start_mae_ms"] = float(np.mean([error[0] for error in interval_errors]))
        metrics["evidence_end_mae_ms"] = float(np.mean([error[1] for error in interval_errors]))
        metrics["evidence_interval_iou"] = float(np.mean(interval_ious))
    return metrics
"""Dependency-free audit of frozen predictions; never fits or repairs a model.

Missing/invalid predictions remain abstentions. Temporal MAE is conditional on a
finite in-window estimate; success within tolerance uses all true contact events.
"""

from __future__ import annotations

import argparse
import gzip
import hashlib
import json
import math
import random
import statistics
from collections import Counter
from pathlib import Path

CLASSES = ("free", "intentional", "accidental")
JOINTS = {f"J{i}" for i in range(1, 8)}
KEYS = {
    "contact",
    "event_type",
    "onset_ms",
    "strongest_joint",
    "affected_joints",
    "evidence_start_ms",
    "evidence_end_ms",
}
MODELS = {
    "features": "Signal features + logistic regression",
    "opentslm": "OpenTSLM canary-v4 (trained Llama 3.2 1B)",
    "qwen": "Qwen3-VL 4B, zero-shot plots",
    "zero-signal": "OpenTSLM zero-signal ablation",
}


def read_bytes(path: Path) -> bytes:
    data = path.read_bytes()
    return gzip.decompress(data) if path.suffix == ".gz" else data


def rows(path: Path) -> list[dict]:
    return [json.loads(line) for line in read_bytes(path).splitlines() if line.strip()]


def unique_index(items: list[dict]) -> dict[str, dict]:
    result = {}
    for row in items:
        key = row["record_id"]
        if key in result:
            raise ValueError(f"Duplicate record ID: {key}")
        result[key] = row
    return result


def time_valid(value: object, *, endpoint: bool = False) -> bool:
    return (
        type(value) in (int, float)
        and math.isfinite(value)
        and 0 <= value <= 1024
        and (endpoint or value < 1024)
    )


def schema_valid(p: object) -> bool:
    if not isinstance(p, dict) or set(p) != KEYS:
        return False
    if type(p["contact"]) is not bool or p["event_type"] not in CLASSES:
        return False
    affected = p["affected_joints"]
    if (
        not isinstance(affected, list)
        or any(type(j) is not str or j not in JOINTS for j in affected)
        or len(set(affected)) != len(affected)
    ):
        return False
    if not p["contact"]:
        return (
            p["event_type"] == "free"
            and not affected
            and all(
                p[k] is None for k in ("onset_ms", "strongest_joint", "evidence_start_ms", "evidence_end_ms")
            )
        )
    return (
        p["event_type"] != "free"
        and p["strongest_joint"] in affected
        and time_valid(p["onset_ms"])
        and time_valid(p["evidence_start_ms"])
        and time_valid(p["evidence_end_ms"], endpoint=True)
        and p["evidence_start_ms"] < p["evidence_end_ms"]
    )


def score(items: list[dict]) -> dict:
    n = len(items)
    if not n:
        raise ValueError("Cannot score an empty evaluation")
    confusion = {c: Counter() for c in CLASSES}
    contact_confusion = {"false": Counter(), "true": Counter()}
    valid = parsed = contact_valid = contact_correct = joint_correct = 0
    errors = []
    event_n = 0
    affected_scores = []
    for row in items:
        target, p = row["target"], row.get("prediction")
        parsed += isinstance(p, dict)
        valid += schema_valid(p)
        p = p if isinstance(p, dict) else {}
        pred_class = p.get("event_type")
        pred_class = pred_class if isinstance(pred_class, str) and pred_class in CLASSES else "abstain"
        confusion[target["event_type"]][pred_class] += 1
        contact = p.get("contact")
        is_bool = type(contact) is bool
        contact_valid += is_bool
        contact_correct += is_bool and contact == target["contact"]
        contact_confusion[str(target["contact"]).lower()][str(contact).lower() if is_bool else "abstain"] += 1
        if target["contact"]:
            event_n += 1
            joint_correct += p.get("strongest_joint") == target["strongest_joint"]
            onset = p.get("onset_ms")
            if time_valid(onset):
                errors.append(abs(onset - target["onset_ms"]))
            affected = p.get("affected_joints")
            if (
                isinstance(affected, list)
                and all(type(j) is str and j in JOINTS for j in affected)
                and len(set(affected)) == len(affected)
            ):
                truth, predicted = set(target["affected_joints"]), set(affected)
                denominator = len(truth) + len(predicted)
                affected_scores.append(2 * len(truth & predicted) / denominator if denominator else 1.0)
            else:
                affected_scores.append(0.0)
    f1 = {}
    for c in CLASSES:
        tp = confusion[c][c]
        fp = sum(confusion[other][c] for other in CLASSES if other != c)
        fn = sum(confusion[c].values()) - tp
        f1[c] = 2 * tp / (2 * tp + fp + fn) if 2 * tp + fp + fn else 0.0
    contact_f1 = {}
    for c in ("false", "true"):
        other = "true" if c == "false" else "false"
        tp, fp = contact_confusion[c][c], contact_confusion[other][c]
        fn = sum(contact_confusion[c].values()) - tp
        contact_f1[c] = 2 * tp / (2 * tp + fp + fn) if 2 * tp + fp + fn else 0.0
    return {
        "n": n,
        "contact_events": event_n,
        "json_object_rate": parsed / n,
        "usable_summary_rate": valid / n,
        "semantics_macro_f1": statistics.mean(f1.values()),
        "semantics_accuracy": sum(confusion[c][c] for c in CLASSES) / n,
        "semantics_per_class_f1": f1,
        "semantics_confusion": {c: dict(confusion[c]) for c in CLASSES},
        "contact_answer_coverage": contact_valid / n,
        "contact_accuracy": contact_correct / n,
        "contact_macro_f1": statistics.mean(contact_f1.values()),
        "contact_positive_f1": contact_f1["true"],
        "contact_confusion": {c: dict(contact_confusion[c]) for c in contact_confusion},
        "strongest_joint_accuracy": joint_correct / event_n if event_n else None,
        "affected_joint_set_f1_contact_only": statistics.mean(affected_scores) if affected_scores else None,
        "onset_coverage": len(errors) / event_n if event_n else None,
        "onset_mae_ms": statistics.mean(errors) if errors else None,
        "onset_median_ae_ms": statistics.median(errors) if errors else None,
        "onset_within_50ms_all_contacts": sum(e <= 50 for e in errors) / event_n if event_n else None,
    }


def validate_alignment(predictions: dict[str, list[dict]], records: list[dict], splits: dict) -> list[str]:
    prepared = unique_index(records)
    indices = {name: unique_index(items) for name, items in predictions.items()}
    ids = sorted(next(iter(indices.values())))
    if not ids:
        raise ValueError("Empty evaluation")
    for name, index in indices.items():
        if set(index) != set(ids):
            raise ValueError(f"Unequal test record IDs: {name}")
        for key in ids:
            if key not in prepared:
                raise ValueError(f"Unknown prepared record: {key}")
            record, row = prepared[key], index[key]
            if record.get("split") != "test" or splits.get(record["session_id"]) != "test":
                raise ValueError(f"Record is not in held-out test sessions: {key}")
            if row.get("session_id", record["session_id"]) != record["session_id"]:
                raise ValueError(f"Wrong session: {key}")
            target = {k: record["onset_sample"] if k == "onset_ms" else record[k] for k in KEYS}
            if row["target"] != target:
                raise ValueError(f"Target mismatch for {name}: {key}")
            row["session_id"] = record["session_id"]
    return ids


def bootstrap_difference(left: list[dict], right: list[dict], repeats: int, seed: int) -> dict:
    """Paired recording-cluster bootstrap, OpenTSLM minus feature baseline."""
    groups = {}
    right_by_id = unique_index(right)
    for row in left:
        groups.setdefault(row["session_id"], []).append((row, right_by_id[row["record_id"]]))
    sessions = sorted(groups)
    rng = random.Random(seed)
    metrics = (
        "semantics_accuracy",
        "contact_accuracy",
        "usable_summary_rate",
        "onset_within_50ms_all_contacts",
    )
    samples = {key: [] for key in metrics}
    for _ in range(repeats):
        paired = [pair for s in rng.choices(sessions, k=len(sessions)) for pair in groups[s]]
        a, b = score([p[0] for p in paired]), score([p[1] for p in paired])
        for key in metrics:
            if a[key] is not None and b[key] is not None:
                samples[key].append(a[key] - b[key])
    result = {}
    for key, values in samples.items():
        values.sort()
        result[key] = [values[int(0.025 * (len(values) - 1))], values[int(0.975 * (len(values) - 1))]]
    return {
        "method": "paired recording-cluster percentile bootstrap",
        "repeats": repeats,
        "seed": seed,
        "difference": "OpenTSLM minus signal features",
        "interval_95": result,
    }


def build_report(source: Path, repeats: int = 1000) -> dict:
    if repeats < 100:
        raise ValueError("Use at least 100 bootstrap replicates")
    inventory = json.loads((source / "inventory.json").read_text())
    for name, entry in inventory["files"].items():
        if hashlib.sha256(read_bytes(source / name)).hexdigest() != entry["sha256_uncompressed"]:
            raise ValueError(f"Source checksum mismatch: {name}")
    predictions = {name: rows(source / f"{name}.jsonl.gz") for name in MODELS}
    records = rows(source / "test-records.jsonl.gz")
    splits = json.loads((source / "splits.json").read_text())
    ids = validate_alignment(predictions, records, splits)
    records_hash = hashlib.sha256(read_bytes(source / "test-records.jsonl.gz")).hexdigest()
    for name in ("features", "qwen"):
        manifest = json.loads((source / f"{name}-manifest.json").read_text())
        if manifest["split"] != "test" or manifest["prepared_records_sha256"] != records_hash:
            raise ValueError(f"Wrong prepared records manifest: {name}")
        manifest_ids = manifest.get("record_ids") or [r["record_id"] for r in manifest["records"]]
        if len(manifest_ids) != len(ids) or set(manifest_ids) != set(ids):
            raise ValueError(f"Wrong selection manifest: {name}")
    return {
        "schema_version": 1,
        "split": "test",
        "selection_seed": 20260912,
        "window_count": len(ids),
        "recording_count": len({r["session_id"] for r in predictions["features"]}),
        "class_counts": dict(Counter(r["target"]["event_type"] for r in predictions["features"])),
        "record_ids_sha256": hashlib.sha256(("\n".join(ids) + "\n").encode()).hexdigest(),
        "checkpoint_sha256": inventory["checkpoint_sha256"],
        "source_inventory_sha256": hashlib.sha256((source / "inventory.json").read_bytes()).hexdigest(),
        "models": {name: {"label": MODELS[name], **score(items)} for name, items in predictions.items()},
        "paired_uncertainty": bootstrap_difference(
            predictions["opentslm"], predictions["features"], repeats, 20260912
"""Natural-language prompt families and machine-parseable answer targets."""

from __future__ import annotations

import json
from typing import Literal

from robot_observability.constants import JOINT_NAMES

Intent = Literal[
    "summary",
    "contact",
    "semantics",
    "onset",
    "strongest_joint",
    "affected_joints",
    "evidence_interval",
]

INTENTS: tuple[Intent, ...] = (
    "summary",
    "contact",
    "semantics",
    "onset",
    "strongest_joint",
    "affected_joints",
    "evidence_interval",
)

PROMPTS: dict[Intent, tuple[str, ...]] = {
    "summary": (
        "Diagnose this robot telemetry window.",
        "Summarize the contact event and identify the supporting temporal evidence.",
    ),
    "contact": (
        "Did external contact occur?",
        "Does this window contain evidence of physical contact?",
    ),
    "semantics": (
        "Was the motion free, an intentional contact, or an accidental collision?",
        "Classify the interaction semantics.",
    ),
    "onset": (
        "When did external contact begin?",
        "Give the contact onset relative to the start of this window in milliseconds.",
    ),
    "strongest_joint": (
        "Which joint has the strongest normalized disturbance evidence?",
        "Identify the joint whose torque signal most strongly supports the diagnosis.",
    ),
    "affected_joints": (
        "Which joints are materially affected, ranked by disturbance?",
        "List the joints crossing the calibrated disturbance threshold.",
    ),
    "evidence_interval": (
        "Where is the strongest temporal evidence?",
        "Return the interval containing sustained disturbance evidence.",
    ),
}


def answer_payload(metadata: dict[str, object], intent: Intent) -> dict[str, object]:
    complete = {
        "contact": bool(metadata["contact"]),
        "event_type": metadata["event_type"],
        "onset_ms": metadata["onset_sample"],
        "strongest_joint": metadata["strongest_joint"],
        "affected_joints": metadata["affected_joints"],
        "evidence_start_ms": metadata["evidence_start_ms"],
        "evidence_end_ms": metadata["evidence_end_ms"],
    }
    keys: dict[Intent, tuple[str, ...]] = {
        "summary": tuple(complete),
        "contact": ("contact",),
        "semantics": ("event_type",),
        "onset": ("onset_ms",),
        "strongest_joint": ("strongest_joint",),
        "affected_joints": ("affected_joints",),
        "evidence_interval": ("evidence_start_ms", "evidence_end_ms"),
    }
    return {key: complete[key] for key in keys[intent]}


def evidence_sentence(metadata: dict[str, object]) -> str:
    if not metadata["contact"]:
        return (
            "Across J1–J7, no sustained torque disturbance crosses the threshold calibrated only "
            "on training free-motion recordings, so no localized onset or responsible joint is supported."
        )
    scores = list(metadata["joint_scores"])
    ranked = sorted(zip(JOINT_NAMES, scores), key=lambda pair: -pair[1])
    affected = list(metadata["affected_joints"])
    affected_text = ", ".join(affected) if affected else "no additional joints"
    return (
        f"A sustained torque excursion begins near {metadata['onset_sample']} ms and its strongest "
        f"evidence spans {metadata['evidence_start_ms']}–{metadata['evidence_end_ms']} ms; "
        f"{ranked[0][0]} has the largest normalized disturbance, with threshold-crossing support "
        f"from {affected_text}."
    )


def target_text(
    metadata: dict[str, object],
    intent: Intent,
    output_format: str = "answer_then_evidence",
) -> str:
    payload = json.dumps(answer_payload(metadata, intent), separators=(",", ":"), sort_keys=True)
    rationale = evidence_sentence(metadata)
    if output_format == "answer_then_evidence":
        return f"Answer: {payload}\nEvidence: {rationale}"
    if output_format == "rationale_then_answer":
        return f"Rationale: {rationale}\nAnswer: {payload}"
    raise ValueError(f"Unknown output format: {output_format}")


def channel_descriptions(metadata: dict[str, object]) -> list[str]:
    del metadata
    return [
        (
            f"{joint} external joint torque in Nm, sampled at 1000 Hz over 1.024 seconds. "
            "The numeric values are normalized with train-only robust statistics."
        )
        for joint in JOINT_NAMES
    ]
"""Adapter from prepared robot windows to OpenTSLM's sample contract."""

from __future__ import annotations

import hashlib
import json
from pathlib import Path

from robot_observability.prepared import PreparedSplit
from robot_observability.qa import INTENTS, PROMPTS, answer_payload, channel_descriptions, target_text


class RobotQADataset:
    """A torch-compatible dataset without importing torch at module import time."""

    def __init__(
        self,
        root: Path,
        split: str,
        *,
        mode: str = "summary_plus_atomic",
        seed: int = 20260912,
        eos_token: str = "",
        output_format: str = "answer_then_evidence",
    ) -> None:
        self.prepared = PreparedSplit(root, split)
        if mode not in {"mixed", "summary", "summary_plus_atomic", "all_intents"}:
            raise ValueError(f"Unknown prompt mode: {mode}")
        self.mode = mode
        self.seed = seed
        self.eos_token = eos_token
        if output_format not in {"answer_then_evidence", "rationale_then_answer"}:
            raise ValueError(f"Unknown output format: {output_format}")
        self.output_format = output_format

    def __len__(self) -> int:
        multiplier = (
            len(INTENTS) if self.mode == "all_intents" else 2 if self.mode == "summary_plus_atomic" else 1
        )
        return len(self.prepared) * multiplier

    def __getitem__(self, index: int) -> dict[str, object]:
        import torch

        multiplier = (
            len(INTENTS) if self.mode == "all_intents" else 2 if self.mode == "summary_plus_atomic" else 1
        )
        row_index, intent_index = divmod(index, multiplier)
        signal, metadata = self.prepared[row_index]
        if self.mode == "all_intents":
            intent = INTENTS[intent_index]
        elif self.mode == "mixed":
            digest = hashlib.sha256(f"{self.seed}:{metadata['record_id']}:mixed".encode()).digest()
            if digest[0] % 2 == 0:
                intent = "summary"
            else:
                intent = INTENTS[1 + int.from_bytes(digest[1:5], "big") % (len(INTENTS) - 1)]
        elif self.mode == "summary_plus_atomic" and intent_index == 1:
            digest = hashlib.sha256(f"{self.seed}:{metadata['record_id']}:atomic".encode()).digest()
            intent = INTENTS[1 + int.from_bytes(digest[:4], "big") % (len(INTENTS) - 1)]
        else:
            intent = "summary"
        variants = PROMPTS[intent]
        digest = hashlib.sha256(f"{self.seed}:{metadata['record_id']}:{intent}".encode()).digest()
        question = variants[int.from_bytes(digest[:4], "big") % len(variants)]
        schema_keys = list(answer_payload(metadata, intent))
        schema = json.dumps(schema_keys, separators=(",", ":"))
        if self.output_format == "rationale_then_answer":
            response_contract = (
                "First write `Rationale:` as one natural paragraph grounded in temporal and joint "
                "patterns. Do not use headings inside it or name the interaction class before the "
                f"final line. End with `Answer:` and one closed compact JSON object containing only {schema}. "
            )
        else:
            response_contract = (
                f"Respond with `Answer:` and one closed compact JSON object containing only {schema}. "
            )
        return {
            "pre_prompt": (
                "You are analyzing synchronized KUKA LWR4+ external-joint-torque telemetry. "
                "Use the numeric time series as primary evidence. "
            ),
            "time_series_text": channel_descriptions(metadata),
            "time_series": torch.from_numpy(signal.astype("float32", copy=True)),
            "post_prompt": (
                f"\nQuestion: {question}\n"
                f"{response_contract}"
                "Use JSON types exactly: booleans are true/false, numbers are unquoted, arrays are "
                "arrays, and missing values are null. Never quote a boolean, number, or null. "
                + (
                    ""
                    if self.output_format == "rationale_then_answer"
                    else "Then write one short `Evidence:` sentence."
                )
            ),
            "answer": target_text(metadata, intent, self.output_format) + self.eos_token,
            "record_id": metadata["record_id"],
            "intent": intent,
            "metadata": metadata,
        }

